Triggers:
CREATE TRIGGER validate_user_email
BEFORE INSERT ON users
FOR EACH ROW
BEGIN
  SELECT CASE
    WHEN NEW.email NOT LIKE '%@%' THEN
      RAISE(ABORT, 'Invalid email address')
  END;
END;

CREATE TRIGGER log_user_changes
AFTER UPDATE ON users
FOR EACH ROW
BEGIN
  INSERT INTO audit_log(table_name, action, record_id, old_value, new_value, changed_at)
  VALUES ('users', 'UPDATE', OLD.id, OLD.email, NEW.email, datetime('now'));
END;

CREATE TRIGGER cascade_delete_orders
BEFORE DELETE ON users
FOR EACH ROW
BEGIN
  DELETE FROM orders WHERE user_id = OLD.id;
END;

-- INSTEAD OF trigger on a view
CREATE VIEW user_summary AS SELECT id, name FROM users;
CREATE TRIGGER instead_of_insert_user
INSTEAD OF INSERT ON user_summary
FOR EACH ROW
BEGIN
  INSERT INTO users (name) VALUES (NEW.name);
END;

DROP TRIGGER IF EXISTS validate_user_email;

