JSON Support:
CREATE TABLE events (
  id INTEGER PRIMARY KEY,
  data TEXT CHECK (json_valid(data))
);

INSERT INTO events (data) VALUES
  ('{"type": "click", "page": "/home", "tags": ["ui", "navigation"], "userId": 42}'),
  ('{"type": "purchase", "total": 29.99, "items": ["book", "pen"], "userId": 7}');

-- Extract values
SELECT json_extract(data, '$.type') AS event_type FROM events;
SELECT data ->> '$.type' AS type, data ->> '$.userId' AS user FROM events;

-- Update JSON
UPDATE events
SET data = json_set(data, '$.page', '/dashboard')
WHERE id = 1;

-- Remove key
UPDATE events
SET data = json_remove(data, '$.tags')
WHERE id = 1;

-- Expand JSON array into rows
SELECT id, value AS tag
FROM events, json_each(data, '$.tags')
WHERE id = 1;

-- Aggregate into JSON array
SELECT
  json_group_array(DISTINCT data ->> '$.type') AS event_types
FROM events;

-- Aggregate into JSON object
SELECT
  json_group_object(
    data ->> '$.type',
    json_extract(data, '$.userId')
  ) AS type_to_user
FROM events;

-- Check if valid JSON
SELECT json_valid('{"a":1}'), json_valid('not json');
-- Returns 1 and 0
